ValidationRule.errorConditionFormula:
AND(
    NOT(Bypass_Validation__c),  /* Skip if bypass is true */
    OR(
        /* Your original conditions */
        ISPICKVAL(Status__c, "Full Day Leave") && ISBLANK(Reason_for_Leave__c),
        ISPICKVAL(Status__c, "Half Day Leave") && ISBLANK(Reason_for_Leave__c)
        /* Add other existing validation conditions here if any */
    )
)
